}
orb.rotation.y=t*.65;orb.rotation.x=Math.sin(t*.4)*.12;hoop.rotation.z=t*.38;beaconLight.intensity=19+Math.sin(t*3)*5;if(toastTimer>0){toastTimer-=dt;if(toastTimer<=0)$('#toast').classList.remove('show')}if(hitTimer>0){hitTimer-=dt;if(hitTimer<=0)$('#hitmarker').classList.remove('on')}if(damageTime>0){damageTime-=dt;if(damageTime<=0)$('#damage').classList.remove('flash')}}
