const { chromium } = require(process.env.HOME+'/.local/share/omgithub-playwright/node_modules/playwright');
(async()=>{const browser=await chromium.launch({executablePath:'/usr/bin/chromium',headless:true,args:['--no-sandbox','--use-gl=angle','--use-angle=swiftshader']});const page=await browser.newPage({viewport:{width:1440,height:900}});page.on('pageerror',e=>console.error('PAGEERROR',e.message));page.on('console',m=>{if(m.type()==='error')console.error('CONSOLE',m.text())});await page.goto('http://localhost:3002',{waitUntil:'networkidle',timeout:60000});await page.screenshot({path:'/tmp/opencode/game.png'});console.log('title:',await page.title(),'canvas:',await page.locator('canvas').count(),'deploy:',await page.locator('#startBtn').innerText());await browser.close()})().catch(e=>{console.error(e);process.exit(1)});
JS

node <<'JS'
const {chromium}=require(process.env.HOME+'/.local/share/omgithub-playwright/node_modules/playwright');
(async()=>{const browser=await chromium.launch({executablePath:'/usr/bin/chromium',headless:true,args:['--no-sandbox','--use-gl=angle','--use-angle=swiftshader']});const page=await browser.newPage({viewport:{width:1440,height:900}});let errors=[];page.on('pageerror',e=>errors.push(e.message));await page.goto('http://localhost:3002',{waitUntil:'networkidle'});await page.locator('#startBtn').click();await page.waitForTimeout(1000);console.log(JSON.stringify({overlayHidden:await page.locator('#overlay').evaluate(e=>e.classList.contains('hidden')),canvas:await page.locator('canvas').evaluate(c=>({width:c.width,height:c.height,webgl:!!(c.getContext('webgl2')||c.getContext('webgl'))})),errors}));await page.screenshot({path:'/tmp/opencode/game-playing.png'});await browser.close()})().catch(e=>{console.error(e);process.exit(1)});
